    let keyspaces = FjallJournal::declared_keyspaces();
    let required = [
        "workflow_source",
        "compiled_ir",
        "run_header",
        "run_inputs",
        "run_event",
        "run_snapshot",
        "blob",
        "index_status",
        "index_workflow",
        "index_action",
        "emergency_deny",
