    let keyspaces = FjallJournal::declared_keyspaces();
    let mut sorted = keyspaces.to_vec();
    sorted.sort();
    sorted.dedup();
    assert_eq!(
        sorted.len(),
        keyspaces.len(),
        "declared_keyspaces must not contain duplicates"
    );
}


