    let raw = journal
        .artifact_acceptance
        .get(b"last_issued")
        .map_err(|e| format!("counter read failed: {e}"))?;
    match raw {
        None => Ok(None),
        Some(slice) => {
            let bytes = slice.as_ref();
            if bytes.len() != 8 {
                return Err(format!("counter wrong length: {}", bytes.len()));
            }
            let arr: [u8; 8] = bytes
                .try_into()
                .map_err(|_| "counter slice conversion failed".to_string())?;
